T("A Suite look, font, minimum height and position for Blizzard dialogs, marked resurrection offers, the item quality written on loot toasts and gold-framed money toasts.", "Apparence, police, hauteur minimale et position de la Suite pour les dialogues de Blizzard, offres de résurrection marquées, qualité d'objet écrite sur les notifications de butin et notifications d'argent encadrées d'or.")
T("A bar cannot attach to itself.", "Une barre ne peut pas s'attacher à elle-même.")
T("A bar cannot send cooldowns to itself.", "Une barre ne peut pas s'envoyer ses propres temps de recharge.")
T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "Un écran cinématique de la Suite avec votre personnage pendant que vous êtes AFK. Bougez ou utilisez /afk pour revenir.")
T("A class in your group can provide this buff.", "Une classe de votre groupe peut fournir cette amélioration.")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "Une minicarte épurée dans son propre cadre : taille, forme, bordure, zoom, boutons Blizzard, tiroir de boutons d'addons et textes d'information. Les boutons de minicarte de Blizzard continuent de fonctionner.")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "Une surface qui laisse passer les clics suit chaque fenêtre de discussion Blizzard. Les modes Édition de Blizzard et de MSUF gardent leurs contrôles habituels de déplacement et de redimensionnement.")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "Une plaque colorée se place derrière la carte et sa bordure. La marge l'étend au-delà du bord de la carte.")
T("A compact, movable history of your recent successful spells.", "Un historique compact et déplaçable de vos derniers sorts lancés avec succès.")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "Un affichage des images par seconde peut se placer sous la bande ou à part, positionné dans le mode Édition de MSUF. Le raccourci FPS de MSUF Suite l'affiche ou le masque pour cette session, même en combat ; un nouveau choix ici remplace ce réglage de session.")
T("A movable strip for critical strike, haste, mastery and versatility.", "Une barre déplaçable pour le coup critique, la hâte, la maîtrise et la polyvalence.")
T("A movable summary after a Mythic+ run or raid boss kill.", "Un résumé déplaçable après un parcours Mythique+ ou la défaite d'un boss de raid.")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "Un anneau bien visible autour du pointeur de la souris, éventuellement rempli par votre temps de recharge global ou votre incantation.")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "Un anneau autour du pointeur de la souris pour le retrouver facilement. Choisissez sa forme, sa taille, sa couleur, une courte traînée et un point central ; « Aucun anneau » ne garde que le point ou le remplissage de progression. Le mode caméra n'affiche l'anneau, le point et la traînée que pendant que vous maintenez un bouton de la souris sur le monde du jeu pour tourner la caméra. La surbrillance ne suit le pointeur que lorsqu'un élément est affiché et ne déplace rien tant que le pointeur reste immobile.")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "Un petit résumé se place à côté de l'onglet Personnage de votre fiche et disparaît avec lui. Il liste votre équipement avec châsses et combien sont remplies, les ouvertes en ambre (cliquez une ligne pour sertir), la durabilité totale de votre équipement et, si vous le souhaitez, votre niveau d'objet JcJ. Ses boutons ouvrent la Grande chambre forte et la page de l'extension actuelle. Il se met à jour tant que la fiche est ouverte, au plus une fois par image.")
T("A soft light behind the map, independent of the border and artwork.", "Une lumière douce derrière la carte, indépendante de la bordure et du décor.")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "Un résumé avec châsses, durabilité, niveau d'objet JcJ et boutons de la Grande chambre forte et de l'extension, la durabilité sur le modèle, des icônes d'emplacement rognées et les niveaux d'objet dans les choix d'équipement.")
