T("Accept and turn in quests automatically. Hold Shift to pause. Reward choices and quests with a money cost stay manual.", "Accepte et rend les quêtes automatiquement. Maintenez Maj pour mettre en pause. Les choix de récompense et les quêtes payantes restent manuels.")
T("Accept guild members", "Accepter les membres de la guilde")
T("Accept only ordinary party invitations from the relationship types you select. Invites remain manual in combat, while grouped, during queue-loss or quest-session confirmations, or when Blizzard asks you to choose a role. The native popup handles the final action.", "Accepte uniquement les invitations de groupe ordinaires provenant des contacts que vous choisissez. L'acceptation reste manuelle en combat, si vous êtes déjà en groupe, si une file d'attente ou une confirmation de quête risque d'être perdue, ou si Blizzard vous demande de choisir un rôle. La fenêtre native effectue l'action finale.")
