T("Ambience", "Ambiance")
T("An MSUF-owned objective tracker with grouped, readable entries.", "Un suivi des objectifs géré par MSUF, avec des entrées groupées et lisibles.")
T("An adjacent button opens a small menu for expansion, Great Vault, Adventure Guide and world map pages. Blizzard's landing button keeps its own click behavior. Menu actions are disabled in combat.", "Un bouton voisin ouvre un petit menu donnant accès à l'extension, à la Grande chambre forte, au Guide d'aventure et à la carte du monde. Le bouton d'accueil de Blizzard conserve son propre fonctionnement. Les actions du menu sont désactivées en combat.")
T("An empty allow-list includes every quest. Separate quest IDs with spaces or commas. Daily and weekly exclusions leave a quest manual if its frequency cannot be read. Existing profiles keep their previous behavior until you enable an exclusion.", "Une liste d'autorisation vide inclut toutes les quêtes. Séparez les ID de quête par des espaces ou des virgules. Les exclusions journalières et hebdomadaires laissent une quête en manuel si sa fréquence est illisible. Les profils existants gardent leur comportement précédent jusqu'à ce que vous activiez une exclusion.")
T("Animated color flashes that celebrate a level, an achievement or Bloodlust, at random times if you like, and can spin the Suite action bars once.", "Des éclairs de couleur animés qui célèbrent un niveau, un haut fait ou une Furie sanguinaire, à des moments aléatoires si vous le souhaitez, et peuvent faire tourner une fois les barres d'action de la Suite.")
