T("At a merchant, review and confirm sales from an explicit item ID list.", "Chez un marchand, examinez et confirmez la vente des objets d'une liste explicite d'ID.")
T("At a trainer, review the count and combined gold cost before buying. The button learns only abilities already available at confirmation, checks each step again, and stops when the trainer closes, combat starts or the list changes. Profession choices and rank steps stay manual.", "Chez un maître de classe, vérifiez le nombre de techniques et leur coût total en or avant l'achat. Le bouton n'apprend que les techniques disponibles au moment de la confirmation, revérifie chaque étape et s'arrête si la fenêtre se ferme, si le combat commence ou si la liste change. Les choix de métier et les rangs restent manuels.")
