T("Bounded named-root traversal\nDedicated visual-only Edit Mode coverage\nExplicit secure controls remain untouched\nBlizzard frames keep their parents and scripts; only Suite-made selection indicators move\nNo polling or tickers; OnUpdate runs only while a window corner is dragged", "Parcours limité des racines nommées\nCouverture dédiée et purement visuelle du mode Édition\nLes contrôles sécurisés explicites restent intacts\nLes cadres Blizzard gardent leurs parents et leurs scripts ; seuls les indicateurs de sélection créés par la Suite se déplacent\nNi interrogation périodique ni tickers ; OnUpdate ne tourne que pendant le glissement d'un coin de fenêtre")
