T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "Les bulles hors des instances peuvent prendre le style MSUF ; Blizzard verrouille celles des instances. Chaque source garde le style de Blizzard ou prend celui de MSUF : le style commun ou sa propre police, taille, couleurs, marges et largeur. Une bulle est associée à la ligne qu'elle affiche juste après l'arrivée de cette ligne. Désactiver les bulles dans les instances utilise les réglages de bulles de Blizzard et les rend quand vous sortez ou désactivez l'option.")
