T("Choose %s for \"%s\".", "Choisissez %s pour « %s ».")
T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "Choisissez Moderne épuré, Midnight Blue, Verre MSUF Forever, Midnight Dark ou Style de classe pour l'habillage et les modules actifs de la Suite. Les modules activés plus tard en héritent.")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "Choisissez Moderne épuré, Midnight Blue, Midnight Dark, MSUF Forever ou Style de classe. Seules les couleurs et l'opacité de la fenêtre des sacs changent ; les emplacements et actions Blizzard sont conservés.")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "Choisissez Clean Modern, Midnight Blue, le verre neutre Midnight Dark ou le cadre doré sombre de MSUF Forever. Tous utilisent la texture de barre et la police MSUF. Activez ou désactivez les 20 segments d'EXP. La ligne inférieure peut afficher l'EXP gagnée pendant la session, l'EXP par heure et le temps restant avant le prochain niveau. Déplacez ou redimensionnez la barre dans le mode Édition MSUF ; sa fenêtre permet de régler X, Y, largeur, hauteur et échelle. Survolez la barre pour voir les valeurs exactes. La session survit à /reload et recommence à la connexion suivante.")
T("Choose Clean Modern, classic MSUF or the complete Forever factory.", "Choisissez Moderne épuré, MSUF classique ou les réglages complets Forever.")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "Choisissez Disposition personnalisée pour définir l'ordre des valeurs totales, par seconde et en pourcentage, puis choisissez des espaces, des crochets ou un séparateur. L'option de pourcentage contrôle les lignes principales ; les lignes de détail affichent les parts disponibles. Les parts indisponibles sont omises. Principale signifie par seconde pour DPS/HPS et total pour les autres compteurs. Les réglages de texte s'appliquent aussi aux en-têtes, aux détails et au chronomètre flottant. Slug utilise le rendu de police net de WoW, avec contour et sans ombre. Les valeurs protégées s'affichent sans pourcentage jusqu'à la fin du combat.")
T("Choose Suite modules", "Choisir les modules de la Suite")
T("Choose a bar to adjust its layout below. The preview uses sample buttons; empty slots and stances can differ in game.", "Choisissez une barre pour ajuster sa disposition ci-dessous. L'aperçu utilise des boutons d'exemple ; les emplacements vides et les postures peuvent différer en jeu.")
T("Choose a font", "Choisir une police")
T("Choose a line, then press Ctrl+C", "Choisissez une ligne, puis appuyez sur Ctrl+C")
T("Choose a look", "Choisir un thème")
T("Choose a look and when the Suite bar appears. Visibility rules use the Suite layout; Blizzard layout keeps Blizzard's visibility. MSUF Edit Mode reveals the bar for moving.", "Choisissez un thème et quand la barre de la Suite apparaît. Les règles de visibilité utilisent la disposition de la Suite ; la disposition Blizzard garde la visibilité de Blizzard. Le mode Édition MSUF révèle la barre pour la déplacer.")
T("Choose a look below; this sample follows your changes.", "Choisissez un thème ci-dessous ; cet exemple suit vos modifications.")
T("Choose a look, then adjust its colors.", "Choisissez un style, puis ajustez ses couleurs.")
T("Choose a preset below or fine-tune with the slider.", "Choisissez un préréglage ci-dessous ou affinez avec le curseur.")
T("Choose a profile that exists in both parts of the suite", "Choisissez un profil qui existe dans les deux parties de la Suite")
T("Choose a random owned Hearthstone variant for the next click", "Choisir aléatoirement une variante de pierre de foyer possédée pour le prochain clic")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "Choisissez une taille de pile inférieure et assurez-vous que l'objet n'est pas verrouillé, que le curseur est vide et que vous êtes hors combat.")
T("Choose a sound", "Choisir un son")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "Choisissez un style ci-dessus ou modifiez ces couleurs pour créer un look personnalisé. Les lignes sont mises à jour immédiatement.")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "Choisissez un style, une police et une couverture en quelques minutes. Tous les réglages avancés restent disponibles en mode Expert.")
T("Choose a template", "Choisissez un modèle")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "Choisissez une police MSUF, un contour, une ombre et un rendu Lisse, Net ou Slug. Slug n'a pas d'ombre. Les couleurs du libellé, de la valeur et d'avertissement sont séparées.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "Choisissez une police et une texture de barre MSUF ou SharedMedia. La taille de police, le contour, l'ombre, le rendu Lisse/Net/Slug, la hauteur de barre et l'espacement mettent l'ATH à jour immédiatement. Slug n'a pas d'ombre.")
T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "Choisissez de grandes familles d'interface. Le comportement sécurisé dédié et les graphismes porteurs de sens restent intacts.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "Choisissez les noms de broker et les identifiants des monnaies découvertes pour chaque emplacement. Sélectionnez vos monnaies d’écus de la saison actuelle dans la liste native ; les choix enregistrés fonctionnent après connexion sans rendre visite au PNJ d’amélioration. L’ordre de sélection et le séparateur contrôlent le bloc d’écus. Les paliers d’amélioration observés restent disponibles comme alternative après avoir sélectionné un objet à améliorer pendant cette session. Les actions de pierre de foyer nécessitent un clic volontaire.")
T("Choose buffs and consumables to track.", "Choisissez les améliorations et consommables à suivre.")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "Choisissez des contrôles de fenêtre épurés et un style complet de micro-barre, puis ajustez des graphismes précis seulement si nécessaire.")
T("Choose coverage", "Choisir la couverture")
T("Choose crest currencies", "Choisir les monnaies d’écus")
T("Choose currencies", "Choisir les monnaies")
T("Choose data for place %d", "Choisir les données de l'emplacement %d")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "Choisissez chaque popup Blizzard séparément. La fonctionnalité masque sa fenêtre lorsqu'elle apparaît et laisse intacts les événements de jeu sous-jacents. Le verrouillage de combat peut empêcher de cacher une fenêtre protégée.")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "Choisissez des erreurs d'interface utilisateur récurrentes individuelles à masquer avec le propre filtre de messages de Blizzard.")
T("Choose observed seasonal stages", "Choisir les paliers saisonniers observés")
T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "Choisissez une police pour le texte de l'interface Blizzard. Les tailles, contours, ombres et la mise à l'échelle d'accessibilité existants sont conservés.")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "Choisissez la vue détaillée du personnage et ses informations supplémentaires. Changer de vue recharge l'interface.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "Choisissez les difficultés de donjon où MSUF lance le journal de combat. En Mythique+, il démarre avec la clé.")
T("Choose the information shown in each bar.", "Choisissez les informations affichées dans chaque barre.")
T("Choose the map shape, then adjust its border and outer shadow.", "Choisissez la forme de la carte, puis ajustez sa bordure et son ombre extérieure.")
T("Choose the raid difficulties where MSUF starts the combat log.", "Choisissez les difficultés de raid où MSUF lance le journal de combat.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "Choisissez les couleurs et le cadre communs des boutons. La disposition, les raccourcis et la visibilité restent tels quels. Modifier une couleur individuelle fait passer le libellé à Personnalisé.")
T("Choose the values shown on each bar.", "Choisissez les valeurs affichées sur chaque barre.")
T("Choose what the Suite tracker lists and when it steps aside.", "Choisissez ce que le suivi Suite affiche et quand il s’efface.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "Choisissez où apparaissent les actions récentes. Les gouffres ont leur propre interrupteur ; les champs de bataille et les arènes en partagent un, et les autres scénarios suivent « Hors des instances ». Là où le suivi est désactivé, il n'écoute pas vos sorts.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "Choisissez quelles interfaces Blizzard reçoivent l'habillage. Blizzard conserve leurs interactions.")
T("Choose your bars", "Choisir vos barres")
T("Choose your profile", "Choisir votre profil")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "Choisir un thème met à jour l'habillage et chaque module actif de la Suite. Les modules activés plus tard en héritent. Les nouveaux profils d'habillage commencent avec %s.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "La confirmation peut être ignorée après votre choix de quitter la cinématique. Le passage automatique est une option distincte qui inclut aussi les vidéos. Les deux sont inactifs en combat, et une séquence en véhicule garde toujours sa confirmation de sortie. Cet assistant peut masquer les didacticiels, préremplir le mot de suppression en vous laissant la confirmation finale, masquer uniquement la confirmation de capture d'écran ou ouvrir votre fiche de personnage chez les marchands, sur le dernier onglet utilisé. À l'hôtel des ventes, le bouton de filtres de Blizzard est marqué tant que « Extension actuelle uniquement » est désactivé ; cochez-le là une fois et Blizzard le garde pour ce personnage.")
T("Cinematic zone and event announcements in the Suite look.", "Annonces cinématiques de zone et d'événement au style de la Suite.")
