T("Clear new toy markers", "Effacer les nouveaux marqueurs de jouets")
T("Clear only new mount, pet and toy fanfares acquired while this helper is active. Your collection entries remain available. Each collection type can be switched off independently.", "Efface uniquement les marqueurs « Nouveau » des montures, mascottes et jouets obtenus lorsque cet assistant est actif. Les objets restent dans votre collection. Chaque type peut être désactivé séparément.")
