T("Click a bar to open the spell breakdown in the window; hover it for a short tooltip.", "Cliquez sur une barre pour ouvrir le détail des sorts dans la fenêtre ; survolez-la pour une infobulle courte.")
T("Click a place to choose its text. Drag the bar in MSUF Edit Mode. Empty places disappear. The Antique Footer preset creates a bag, durability and clock strip on this bar only.", "Cliquez sur un emplacement pour choisir son texte. Déplacez la barre dans le mode Édition MSUF. Les emplacements vides disparaissent. Le préréglage Bas de page antique crée une bande sacs, durabilité et horloge sur cette barre uniquement.")
T("Click a reminder to cast its spell or use its item. Aura checks run on relevant events; there is no repeating scan.", "Cliquez sur un rappel pour lancer son sort ou utiliser son objet. Les vérifications d'aura s'exécutent sur les événements utiles ; il n'y a pas d'analyse répétée.")
T("Click a spell for its settings", "Cliquez sur un sort pour ses réglages")
T("Click again to delete", "Cliquez à nouveau pour supprimer")
T("Click for bag options", "Cliquez pour les options des sacs")
T("Click opens the world map", "Un clic ouvre la carte du monde")
T("Click the minimap button for Blizzard's specialization and loot specialization choices. Choices are disabled in combat and the button hides when both menus are turned off.", "Cliquez sur le bouton de la minicarte pour choisir une spécialisation ou une spécialisation de butin dans les menus de Blizzard. Les choix sont désactivés en combat et le bouton disparaît si les deux menus sont désactivés.")
T("Click to edit this bar, right-click for its actions. Drop a spell here to move it to this bar.", "Cliquez pour modifier cette barre, clic droit pour ses actions. Déposez un sort ici pour le déplacer sur cette barre.")
T("Click to open its Basics: size and attachment.", "Cliquez pour ouvrir ses bases : taille et attache.")
