T("Click to show or hide the collected buttons.", "Cliquez pour afficher ou masquer les boutons regroupés.")
T("Click to stop after the current purchase.", "Cliquez pour arrêter après l'achat en cours.")
T("Click: change live setting; right-click: settings", "Clic : modifier le réglage ; clic droit : réglages")
