T("Color flashes with a banner that names the moment: the level you reached, the achievement you earned, or the Bloodlust-type haste spell that you or your pet cast or that reaches you from anyone in your group (read from your own buffs, which the game may keep hidden during restricted fights). Surprise celebrations can come at random times, around the interval you choose. Spinning turns the Suite action bars once around their centre, only outside combat; entering combat stops the turn at once. Achievements your account had already earned stay quiet. MSUF Edit Mode shows the banner for placing it.", "Des éclairs de couleur avec une bannière qui nomme le moment : le niveau atteint, le haut fait obtenu ou le sort de hâte de type Furie sanguinaire lancé par vous ou votre familier, ou qui vous parvient d'un membre de votre groupe (lu dans vos propres améliorations, que le jeu peut masquer lors des combats restreints). Des célébrations surprises peuvent venir à des moments aléatoires, autour de l'intervalle choisi. La rotation fait tourner une fois les barres d'action de la Suite autour de leur centre, uniquement hors combat ; entrer en combat l'arrête aussitôt. Les hauts faits que votre compte possédait déjà restent discrets. Le mode Édition de MSUF affiche la bannière pour la placer.")
