T("Critical strike, haste, mastery and versatility as your character sheet shows them; leech, avoidance and speed can each join the strip (speed is the stat, not your running speed). Show only in combat hides the strip outside fights. Values the game hides show a dash, and the strip updates from your stat events. MSUF Edit Mode moves the strip.", "Coup critique, hâte, maîtrise et polyvalence tels que votre fiche de personnage les affiche ; la ponction, l'évitement et la vitesse peuvent chacun rejoindre la bande (la vitesse est la caractéristique, pas votre vitesse de course). Afficher seulement en combat masque la bande hors des combats. Les valeurs que le jeu cache affichent un tiret, et la bande suit les événements de vos caractéristiques. Le mode Édition de MSUF déplace la bande.")
