T("Enter a spell name or ID on MSUF action bars. Its buttons glow from this buff on you. A page change in combat pauses the glow until combat ends.", "Saisissez le nom ou l'identifiant d'un sort des barres MSUF. Ses boutons brillent selon cette amélioration sur vous. Un changement de page en combat suspend la lueur jusqu'à la fin du combat.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "Saisissez le nom ou l'identifiant d'un talent ou sort, puis appuyez sur Entrée. Tous les sorts requis doivent être appris. Un champ vide supprime cette condition.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "Saisissez le nom ou l'identifiant d'un talent ou sort, puis appuyez sur Entrée. L'entrée est masquée si l'un des sorts exclus est appris. Les conditions sont actualisées hors combat.")
T("Enter a texture file ID.", "Saisissez un ID de fichier de texture.")
T("Enter a valid spell name or ID", "Entrez un nom de sort ou un identifiant valide")
T("Enter a valid talent or spell name or ID.", "Saisissez un nom ou identifiant valide de talent ou sort.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "Saisissez jusqu'à 200 ID d'objet. Le bouton n'apparaît que chez un marchand et affiche les piles admissibles avant la confirmation. L'assistant revérifie l'identité, la qualité, la valeur, l'état de quête et la position dans le sac avant de demander la vente. L'inclusion des objets équipables nécessite une option distincte.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "Saisissez jusqu'à huit ID de sorts de déplacement. Lorsque vous commencez à bouger, le premier sort connu, prêt et utilisable apparaît brièvement ; un temps de recharge commun de 20 secondes limite les alertes. Les champs vides ne font rien. Le mode Édition MSUF permet de déplacer l'alerte.")
T("Equal", "Égal")
T("Equipment", "Équipement")
T("Equipment category", "Catégorie d'équipement")
T("Equipment choices", "Choix d'équipement")
T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "Les choix d'équipement (la liste qui s'ouvre depuis un emplacement) affichent le niveau de chaque objet pour comparer sans survol. Les flèches à côté des emplacements peuvent être masquées ; maintenez Alt sur un emplacement pour ouvrir ses choix.")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "Les niveaux d'objet de l'équipement apparaissent en haut à droite de chaque emplacement. Choisissez une police, un contour, une ombre et un rendu Lisse, Net ou Slug. Slug n'a pas d'ombre. Les données d'objet manquantes apparaissent dès que le client les fournit.")
