T("Errors and destructive actions", "Erreurs et actions destructrices")
T("Essential bar x/y are an offset from Blizzard's bar", "X/Y de la barre essentielle sont un décalage par rapport à la barre de Blizzard")
T("Essential cooldowns", "Temps de recharge essentiels")
T("Estimated time", "Durée estimée")
T("Event headline colors", "Couleurs des titres d'événement")
T("Every color has a purpose", "Chaque couleur a un rôle")
T("Every color, look, geometry, font, icon, Micro Bar, Blizzard skin and HUD setting travels with the profile.", "Chaque réglage de couleur, de thème, de géométrie, de police, d'icône, de micro-barre, d'habillage Blizzard et d'ATH accompagne le profil.")
T("Every specialization already has it.", "Chaque spécialisation l'a déjà.")
T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "Tous les sorts de cette barre, y compris ceux non appris. Sur une barre de buffs, Ajouter des sorts propose les buffs reçus comme Infusion de puissance et Innervation ; Buff sur moi accepte aussi un ID d'aura de buff ou un nom reconnu, et suit cet ID quel que soit le lanceur. Avec Afficher les buffs manquants désactivé, seuls les buffs actifs apparaissent. L'aperçu modifie aussi les entrées : clic pour les options, glisser pour réordonner ou vers une barre au-dessus, clic milieu pour retirer (annulable). Les sorts retirés restent sous Ajouter des sorts. Les listes sont conservées par spécialisation.")
