T("Fonts, outlines, shadows and Smooth/Sharp/Slug rendering for keybinds, macro names, counts and cooldown numbers. Sizes are set per bar below. Slug has no shadow.", "Polices, contours, ombres et rendu Lisse/Net/Slug pour les raccourcis, noms de macro, compteurs et chiffres de recharge. Les tailles se règlent par barre ci-dessous. Slug n'a pas d'ombre.")
