T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "Masque l'infobulle principale de Blizzard en combat, dans les instances ou pour les objets, sorts et unités sélectionnés. Les infobulles des cadres d'unité et de groupe MSUF conservent leurs propres réglages de visibilité ; celles des auras conservent leurs options Afficher l'infobulle. Chaque choix fonctionne indépendamment. Une infobulle masquée devient entièrement transparente, et Blizzard continue de la gérer normalement.")
