T("Hide only the selected error types. Blizzard keeps handling all other messages and their sounds. Each choice remembers and restores its previous display state when you turn it off.", "Masquez uniquement les types d’erreurs sélectionnés. Blizzard continue de gérer tous les autres messages et leurs sons. Chaque choix mémorise et restaure son état d'affichage précédent lorsque vous l'éteignez.")
