T("Hide the Suite Micro Bar when any selected condition is true. The health condition uses your character's health; at full health the transparent bar can still receive clicks. MSUF Edit Mode shows the bar for placement. Blizzard layout keeps Blizzard's visibility.", "Masque la micro-barre de la Suite quand l'une des conditions choisies est remplie. La condition de vie utilise la vie de votre personnage ; à pleine vie, la barre transparente peut encore recevoir des clics. Le mode Édition MSUF affiche la barre pour la placer. La disposition Blizzard garde la visibilité de Blizzard.")
