T("How the icons line up and grow. A free bar's position counts from the screen center; an attached bar's is an offset from its attach point. Excess cooldowns can move past Maximum icons to another enabled cooldown bar. The destination must have overflow off; chained routes are ignored.", "Alignement et croissance des icônes. La position d'une barre libre est mesurée depuis le centre de l'écran ; celle d'une barre attachée depuis son ancrage. Les temps de recharge dépassant le maximum d'icônes peuvent être transférés vers une autre barre active. Le débordement doit être désactivé sur la destination ; les transferts en chaîne sont ignorés.")
