T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Gardez la grille Blizzard ou choisissez une grille de la Suite, des groupes par sac physique ou des catégories. Utilisez Modifier les catégories dans la fenêtre des sacs pour créer, renommer, réordonner ou désactiver vos catégories ; déposez les objets sur une catégorie latérale pour les affecter. Faites défiler ou utilisez Précédent et Suivant pour les grands inventaires ; en combat, tous les emplacements sont affichés à la fois. Les piles combinées sont uniquement visuelles ; les piles réelles sont toujours rétablies à la banque, à la banque de guilde, au courrier, aux échanges, à l'hôtel des ventes et chez les marchands.")
