T("Limit the whole highlight to combat, to instances or to the open world, then give the pointer ring, the global cooldown and the cast fill their own combat rule. Nothing follows the pointer while it is hidden.", "Limitez toute la surbrillance au combat, aux instances ou au monde ouvert, puis donnez à l'anneau du pointeur, au temps de recharge global et au remplissage d'incantation leur propre règle de combat. Rien ne suit le pointeur tant qu'elle est masquée.")
