T("Loot toasts write the item quality as a word in its color, such as Epic or Rare, next to Blizzard's colored item name; currency toasts stay as they are. Money toasts can get a thin gold frame.", "Les notifications de butin écrivent la qualité de l'objet en toutes lettres dans sa couleur, comme Épique ou Rare, à côté du nom coloré de Blizzard ; celles de monnaie restent inchangées. Les notifications d'argent peuvent recevoir un fin cadre doré.")
