T("MSUF global font (default)", "Police globale MSUF (par défaut)")
T("MSUF icons replace the scattered Blizzard chat controls. Friends, channels, text to speech and the chat menu keep their Blizzard actions; the bottom icon jumps to the newest message. Turn this off to restore the native buttons.", "Des icônes MSUF remplacent les contrôles de discussion Blizzard éparpillés. Amis, canaux, synthèse vocale et menu de discussion gardent leurs actions Blizzard ; l'icône du bas saute au message le plus récent. Désactivez ceci pour rétablir les boutons natifs.")
