T("MSUF look for speech bubbles outside instances", "Style MSUF pour les bulles hors des instances")
T("MSUF looks use Suite glyphs and a player portrait. Blizzard keeps every button action and tooltip.", "Les thèmes MSUF utilisent des glyphes de la Suite et un portrait du joueur. Blizzard conserve chaque action de bouton et chaque infobulle.")
T("MSUF profile system unavailable", "Système de profils MSUF indisponible")
