T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "Ennemis observés additionne les forces ennemies des ennemis vivants en combat que vous voyez via une barre de nom ou votre cible, et le total qu’ils apporteraient. Les ennemis qui ne donnent pas de forces comptent pour zéro ; tant que le client masque une valeur, la ligne affiche -- au lieu d’une estimation. Les ennemis hors de vue ne sont pas comptés.")
