T("One combined bag with a clear Suite background and item levels on equipment. Keep Blizzard's own item grid, or choose a Suite view with pages, bag groups or categories. Using and sorting items stays Blizzard's.", "Un sac combiné avec un fond de Suite net et les niveaux d'objet sur l'équipement. Gardez la grille d'objets de Blizzard ou choisissez une vue de la Suite avec des pages, des groupes par sac ou des catégories. L'utilisation et le tri des objets restent ceux de Blizzard.")
T("One of your Beacons is on nobody in the group.", "L'un de vos Guides n'est sur personne du groupe.")
T("One row", "Une rangée")
T("Only a cooldown bar can take excess cooldowns.", "Seule une barre de temps de recharge peut recevoir l'excédent.")
T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "Seuls les conteneurs obtenus après l'activation de cet assistant s'ouvrent. Il attend la fin du combat, les ouvre un par un et vous les laisse tant que vous maintenez Maj ou qu'une fenêtre de butin ou une fenêtre qui donne un autre sens à l'utilisation d'un objet est ouverte : marchand, banque, banque de guilde, courrier, échange, hôtel des ventes, recycleur, sertissage, amélioration, etc. Les conteneurs de bataillon restent fermés sauf si vous les autorisez ; les profils qui utilisaient déjà cet assistant continuent de les ouvrir. Les paiements d'artisan de Midnight peuvent attendre tant que vos Éclats de Dundun sont à la limite.")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "Uniquement dans un Gouffre actif et hors combat : si le choix du joueur présente exactement une option de sort activée, un bouton et aucune confirmation, MSUF la sélectionne une seule fois. Les autres choix restent manuels.")
