T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "Ouvre votre fiche de personnage, sur le dernier onglet utilisé, à l'ouverture d'un marchand d'amélioration d'objets. Ne ferme qu'une fenêtre ouverte par cet assistant et attend la fin du combat pour l'ouvrir ou la fermer.")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "Paramètres Blizzard facultatifs pour le chat, la carte, le son et les flashs d'écran de faible santé ou alternatifs. MSUF restaure la valeur précédente lorsque vous désactivez un choix ou cet assistant. Les modifications que vous apportez vous-même dans les paramètres de Blizzard pendant l'exécution de cet assistant sont respectées.")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "Contrôles facultatifs de décor et d'espacement. Utilisez le mode Édition MSUF pour la position, le décalage fin, la réinitialisation, l'annulation et le rétablissement.")
