T("Repair equipment and sell poor-quality items when a merchant opens. Hold Shift to skip selling.", "Répare l'équipement et vend les objets de qualité médiocre à l'ouverture d'un marchand. Maintenez Maj pour ne pas vendre.")
T("Repairs only when the cost is within your limit. Guild funds are used first when allowed.", "Répare uniquement si le coût reste dans votre limite. Les fonds de guilde sont utilisés en premier si c'est autorisé.")
T("Replace Blizzard event banners", "Remplacer les bannières d'événement Blizzard")
T("Replace objectives with the Mythic+ timer during a key", "Remplacer les objectifs par le chrono Mythique+ pendant une clé")
T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "Remplace les pages du marchand par une seule liste ; faites-la défiler avec la molette ou la barre. Le clic droit achète, le clic gauche prend un objet et Maj-clic demande une quantité ; les liens et l'aperçu fonctionnent comme d'habitude. Les achats payés en monnaies ou en objets, ou coûtant au moins 150 pièces d'or, demandent d'abord une confirmation. L'onglet de rachat garde la présentation de Blizzard. Déposez un objet de vos sacs sur la liste ou cliquez dessus avec pour le vendre ; un objet encore remboursable demande s'il faut le rembourser.")
T("Report junk sale requests in chat", "Signaler dans la discussion les ventes de camelote")
T("Reports group member deaths in chat during combat.", "Signale dans le chat les décès des membres du groupe pendant le combat.")
T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "Signale la première mort observée de chaque membre du groupe en combat. Le chat local, le message à l'écran et le son sont sélectionnables séparément. Les morts simultanées partagent un seul son. Vous pouvez inclure votre propre mort. La détection n'est active qu'en groupe et en combat.")
T("Reputation", "Réputation")
