T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "Restaure les sorts et buffs par défaut de cette barre pour votre spécialisation. Les autres barres et spécialisations restent inchangées. Vous pouvez annuler.")
T("Results and details", "Résultats et détails")
T("Resurrection offers", "Offres de résurrection")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "Druides Retail uniquement. Chaque chuchotement reçu en combat est une demande d'Innervation possible ; le texte des messages ne peut pas être lu de façon fiable pendant le verrouillage de la discussion. L'alerte attend un temps de recharge d'Innervation connu publiquement, ou affiche une alerte générique quand la disponibilité est inconnue. Une cible préférée peut être entourée sur un cadre de groupe MSUF résolu hors combat. Le mode Édition MSUF prévisualise l'alerte et modifie sa position et sa taille.")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "Retail uniquement. Affiché quand le vol dynamique est disponible, ou seulement en vol si choisi. Sélectionnez barres ou gemmes de vigueur Blizzard ; échelle et son de recharge sont facultatifs. Les hauteurs séparées, la taille de l’icône d’impulsion et les décalages de vitesse sont sous Texte et barres. Le mode édition MSUF affiche un aperçu. Les charges inconnues sont des tirets.")
T("Return to the current fight when combat starts", "Revenir au combat actuel au début d'un combat")
T("Returns this specialization to its short raid essentials list. Your other bars and specializations stay as they are. You can undo it.", "Ramène cette spécialisation à sa courte liste d'essentiels de raid. Vos autres barres et spécialisations restent inchangées. Vous pouvez annuler.")
