T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "Affiche la météo sous forme de texte, d'icône ou des deux. Choisissez les icônes Blizzard ou les illustrations originales Forever. L'infobulle conserve le nom de la météo lorsque seule l'icône est affichée.")
T("Show weekly reward item levels", "Niveaux d'objet des récompenses hebdo")
T("Show who each cast targets", "Afficher la cible de chaque incantation")
T("Show windows", "Afficher les fenêtres")
T("Show your Bloodlust exhaustion or ready state while grouped.", "Affiche votre épuisement après Furie sanguinaire ou l'état prêt lorsque vous êtes en groupe.")
T("Show your owned item count, including bank and Warband bank, on item tooltips.", "Affiche dans les infobulles des objets la quantité que vous possédez, y compris dans la banque et la banque du bataillon.")
T("Show your selected loot specialization in the Great Vault window.", "Affiche votre spécialisation du butin choisie dans la fenêtre de la Grande chambre forte.")
T("Show zone", "Afficher la zone")
T("Shown value", "Valeur affichée")
T("Shown windows: %d. Raise the number of windows to show this one.", "Fenêtres affichées : %d. Augmentez le nombre de fenêtres pour afficher celle-ci.")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "Affiche les charges de résurrection en combat partagées de Blizzard pendant une clé Mythique+ ou une rencontre de raid active. L'icône décompte jusqu'à la prochaine charge avec l'affichage de recharge de Blizzard. Masqué quand la réserve partagée est indisponible. Le mode Édition MSUF prévisualise l'affichage et modifie X, Y, la largeur, la hauteur et l'échelle.")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "Affiche une distance approximative jusqu'à votre cible actuelle d'après les vérifications de portée du jeu pour les sorts que vous connaissez ; les valeurs incluent la zone d'impact de la cible, et des tirets signifient qu'aucun sort connu ne permet de le savoir. Rédigez le texte avec {range} et {unit}. L'estimation peut se placer sous le cadre de la cible, en le suivant quand le cadre bouge, ou n'importe où à l'écran ; le mode Édition de MSUF déplace les deux placements.")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "Affiche le niveau d'objet sur l'équipement des marchands quand Blizzard a chargé ses données. Les objets de rachat et les objets sans niveau d'objet restent inchangés.")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "Affiche la spécialisation du butin actuelle quand vous ouvrez la Grande chambre forte. Se met à jour si vous changez de spécialisation du butin pendant que la fenêtre est ouverte.")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "Affiche hors combat la durabilité équipée la plus basse sous votre seuil choisi. Le mode Édition MSUF affiche un exemple même quand votre équipement est réparé. Sa fenêtre modifie X, Y, la largeur, la hauteur et l'échelle.")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "Affiche combien d'objets vous possédez, y compris dans la banque et la banque du bataillon, lorsque l'infobulle contient un ID d'objet public. Vous pouvez séparer les emplacements de stockage. Les quantités nulles sont omises.")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "Affiche la durabilité totale de votre équipement sur le modèle du personnage, déplacée par les deux décalages, et rogne les bords des icônes d'emplacement sur votre fiche et dans la fenêtre d'inspection.")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "Affiche jusqu'à trois notifications compactes supplémentaires pour le butin personnel de Blizzard. Filtrez par qualité minimale, objets de monture ou de mascotte et, facultativement, jusqu'à 100 ID d'objet. Les notifications natives de Blizzard restent visibles ; les ajouts ordinaires aux sacs sans notification ne sont pas inclus.")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "Affiche votre configuration de talents et votre spécialisation de butin actuelles lors d'une vérification de l'état prêt, lorsqu'une file de donjon apparaît ou à l'entrée d'une instance. Ne change jamais vos talents ni votre spécialisation de butin.")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "Affiche vos derniers sorts lancés avec succès. Les lignes standard ont une icône, un nom et un marqueur ; « Icônes uniquement » forme une colonne verticale compacte. La largeur d'affichage concerne les lignes standard ; dans le mode icônes, la largeur dépend de la hauteur des lignes. La position et l'ancrage se règlent dans le mode Édition MSUF, qui affiche des actions d'exemple. La liste cesse d'écouter les événements lorsqu'elle est désactivée. Les sorts dont le client garde les détails privés ne peuvent pas apparaître.")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "Affiche votre propre épuisement après Furie sanguinaire en groupe, ou l'état prêt si vous préférez. Les changements pertinents de vos auras l'actualisent. Le mode Édition MSUF permet de le déplacer et d'apercevoir l'état d'épuisement.")
