T("Static HUD surfaces are compiled out of combat. Dynamic meter rows never trigger skin mutations or queued work during combat. Meter windows opened later are styled after the next reload or when a setting on this page changes.", "Les surfaces statiques de l'ATH sont préparées hors combat. Les lignes dynamiques du compteur ne déclenchent jamais de modification d'habillage ni de travail en file d'attente en combat. Les fenêtres du compteur ouvertes plus tard sont habillées après le prochain rechargement ou quand un réglage de cette page change.")
