T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Choisissez les onglets natifs, la banque combinée, la banque de bataillon combinée ou les catégories partagées avec le bouton sous la fenêtre de la banque. Ces catégories comprennent les onglets accessibles du personnage et du bataillon. Gérer les onglets de banque ouvre les achats, dépôts et réglages Blizzard. Chaque emplacement garde sa propre action et les piles bancaires ne sont jamais fusionnées ; un clic sur un objet du bataillon sélectionne d'abord l'onglet Banque de bataillon de Blizzard, et un objet remboursable demande confirmation avant d'entrer dans la banque de bataillon.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Open Customize a bar below for layout and other options.", "Activez ou désactivez chaque barre ici. La réactiver rétablit son mode de visibilité précédent. Ouvrez Personnaliser une barre ci-dessous pour la disposition et les autres options.")
