T("That bar shows buffs.", "Cette barre affiche des buffs.")
T("That bar shows cooldowns.", "Cette barre affiche des temps de recharge.")
T("That changed since, so it cannot be undone.", "Cela a changé depuis, donc impossible d'annuler.")
T("That did not work.", "Cela n'a pas fonctionné.")
T("That macro name already exists", "Ce nom de macro existe déjà")
T("The Glass material with MSUF Forever graphite, ivory and muted-gold colors.", "Le matériau Verre avec les couleurs graphite, ivoire et or sourd de MSUF Forever.")
T("The Great Vault is available only in Retail", "La Grande chambre forte n'est disponible que sur Retail")
T("The Mapko skin for Blizzard nameplates. Blizzard keeps health, threat, casts, auras, selection and click handling.", "L'habillage Mapko des plaques de nom Blizzard. Blizzard conserve la gestion de la vie, de la menace, des sorts, des auras, de la sélection et des clics.")
T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "La page Gestionnaire des temps de recharge (CDM) de Suite affiche les temps de recharge et les améliorations suivis par Blizzard sous forme de barres que vous pouvez disposer et personnaliser librement.")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "La page Minicarte de Suite personnalise la minicarte elle-même : taille, forme, bordure, zoom, boutons et textes d'information. L'icône de minicarte de MSUF se trouve dans Divers.")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "La page Barres de nom de Suite personnalise les barres de nom ennemies et alliées de Blizzard. Les filtres d'auras de MSUF déterminent uniquement si les auras réservées aux barres de nom s'affichent sur les cadres de MSUF.")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, and tracked achievements. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "La Suite dessine son propre suivi et masque celui de Blizzard tant qu’elle tourne. Les entrées sont triées en groupes : la quête ciblée, les quêtes de campagne et importantes, les quêtes prêtes à rendre, les quêtes normales, les expéditions, les objectifs bonus proches, les étapes de scénario et de gouffre, et les hauts faits suivis. En raid, il peut disparaître entièrement, seulement pendant un boss ou suspendre la liste normale pendant tout combat de raid ; la vue de rencontre continue alors. Les symboles de quête sont des lettres Suite ou des icônes Blizzard, et la ligne d’en-tête peut être désactivée. Le raccourci « Utiliser l’objet de quête suivi » utilise l’objet de la quête ciblée, sinon le premier utilisable, et ne choisit un nouvel objet qu’hors combat. Clic gauche sur un nom de groupe pour le replier ou sur une quête pour ouvrir son entrée du journal ; clic droit pour plus d’actions.")
T("The Suite frames Blizzard's original Micro Buttons. Their artwork, clicks, tooltips, enabled states and notifications stay native. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "La Suite encadre les micro-boutons d'origine de Blizzard. Leurs graphismes, clics, infobulles, états d'activation et notifications restent d'origine. Les indicateurs de file d'attente et de FPS restent à leur position du mode Édition de Blizzard. Aucune mise à jour récurrente de MSKIN ne s'exécute.")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "L'apparence de la Suite donne aux dialogues de Blizzard un panneau sombre, et la police de la Suite fixe la police et la taille de leur texte ; chacune fonctionne seule, et sans elles les dialogues gardent l'apparence et les polices de Blizzard. Une hauteur minimale agrandit les dialogues courts une fois que Blizzard les a dimensionnés ; 0 garde la hauteur de Blizzard. Une position personnalisée déplace le premier dialogue et ceux que Blizzard empile dessous ; placez-le et réglez la hauteur dans le mode Édition de MSUF.")
T("The Suite skin engine is unavailable.", "Le moteur d'habillage de la Suite est indisponible.")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "Le profil choisi fournit tous les réglages. Choisissez quels modules de la Suite y sont activés.")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "Le buff de classe n'est inclus que si votre personnage le connaît. Saisissez les ID de sorts de buffs personnels séparés par des espaces ou des virgules. Pour un consommable, saisissez ID objet:ID aura ; séparez les paires par des virgules. Jusqu'à 12 rappels au total sont affichés. Les objets d'enchantement d'arme utilisent l'état d'enchantement de la main droite ou gauche.")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "Le sac combiné et le sac de composants utilisent un panneau de la Suite avec un en-tête, une bordure et une ligne d'accent distincts. Réglez l'opacité du fond sur 0 pour une fenêtre transparente ; les emplacements d'objets restent visibles.")
T("The combined bag setting is protected on this client", "Le réglage du sac combiné est protégé sur ce client")
T("The configuration cannot be opened during combat.", "La configuration ne peut pas être ouverte en combat.")
T("The cooldown manager is not loaded.", "Le gestionnaire de temps de recharge n'est pas chargé.")
T("The cooldown manager needs an update. Reload the interface.", "Le gestionnaire de temps de recharge doit être mis à jour. Rechargez l'interface.")
T("The cooldown manager was reset: settings, spell lists and spell options.", "Le gestionnaire de temps de recharge a été réinitialisé : réglages, listes de sorts et options de sort.")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "Le compte à rebours passe à la couleur d'alerte sous ce nombre de secondes. Toutes les barres : le réglage de la section Texte.")
T("The dark sweep over the icon while it counts down.", "Le voile sombre qui balaie l'icône pendant le décompte.")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "La police par défaut suit les polices MSUF tandis que la taille par défaut suit la taille de discussion de Blizzard. Choisissez Police de discussion Blizzard pour garder sa propre police. Slug n'a pas d'ombre.")
T("The dungeon's timer", "Le chronomètre du donjon")
T("The engine remains dormant until a lifecycle event or an explicit user action requires work.", "Le moteur reste en sommeil jusqu'à ce qu'un événement du cycle de vie ou une action explicite de l'utilisateur demande du travail.")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "Le temps de recharge global peut quitter l'anneau pour un cercle fixe de taille et d'opacité propres, affiché à côté des incantations. Placez-le dans le mode Édition de MSUF ; son bouton y fonctionne tant que ce choix est actif.")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "L'en-tête affiche le compteur et le combat. Ses boutons changent le compteur et le combat directement dans la fenêtre.")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "La notification de clé reste locale. L'annonce de groupe facultative transmet uniquement le message de réinitialisation confirmé de Blizzard juste après votre propre demande, si vous dirigez le groupe. Les tentatives échouées et les réinitialisations d'autres joueurs ne sont pas annoncées.")
T("The macro builder is available only in Retail", "Le générateur de macros est disponible uniquement sur Retail")
T("The macro exceeds the 255-character limit", "La macro dépasse la limite de 255 caractères")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "La carte s'agrandit ou se réduit à la largeur et à la hauteur choisies tant que le pointeur la survole, puis revient à sa taille normale. Une carte ronde garde une hauteur égale à sa largeur.")
T("The merchant's offers changed; nothing was bought.", "Les offres du marchand ont changé ; rien n'a été acheté.")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "Tout le stock du marchand dans une liste défilante avec prix, couleurs de qualité et niveaux d'objet.")
T("The minutes below", "Les minutes ci-dessous")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "La molette de la souris zoome la carte. Le clic milieu exécute l'action choisie ; les clics gauche et droit fonctionnent comme d'habitude.")
T("The native input box keeps autocomplete, links and chat commands.", "Le champ de saisie natif conserve l'autocomplétion, les liens et les commandes de discussion.")
T("The normal warning time", "Le délai d'alerte normal")
T("The optional glyph layer changes appearance while Blizzard keeps clicks, tooltips, enabled states and notifications. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "La couche de glyphes optionnelle change l'apparence tandis que Blizzard conserve les clics, infobulles, états d'activation et notifications. Les indicateurs de file d'attente et de FPS restent à leur position du mode Édition de Blizzard. Aucune mise à jour récurrente de MSKIN ne s'exécute.")
T("The options module could not be loaded: %s", "Le module d'options n'a pas pu être chargé : %s")
T("The options module did not finish initializing.", "Le module d'options n'a pas terminé son initialisation.")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "Le tableau du groupe s’enrichit par étapes : personnages avec profil et score, puis les chiffres de combat du compteur de dégâts de Blizzard, puis le butin vu dans la discussion. Chaque personnage garde ses derniers parcours ; ouvrez le plus récent ici ou avec /msufruns et remontez vers les plus anciens. Supprimer un parcours demande un second clic. La carte peut attendre que vous fermiez la fenêtre de butin du coffre.")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "L'aperçu et toutes les sections ci-dessous modifient cette barre. Les groupes personnalisés partagés commencent avec une liste distincte d'identifiants explicites de sorts, d'auras et d'objets ; désactiver le partage rétablit la liste existante par spécialisation.")
T("The preview needs the cooldown manager.", "L'aperçu nécessite le gestionnaire de temps de recharge.")
T("The quick switch above remembers this mode when you turn the bar off. Choose Never to keep it hidden.", "Le bouton rapide ci-dessus mémorise ce mode quand vous désactivez la barre. Choisissez Jamais pour la garder masquée.")
T("The settings you change most. Attach the bar to another bar or to your player frame to keep them together; the gap is the space between them. Center keeps the first cooldown icon in the middle and adds the next icons right, left, right, left. Visible buffs stay compact; on a horizontal mixed bar, player and target buffs grow outward from the center on one row.", "Les réglages que vous modifiez le plus. Attachez la barre à une autre barre ou à votre cadre de joueur pour les garder ensemble ; l'écart est l'espace entre elles. Centre garde la première icône de recharge au milieu et ajoute les suivantes à droite, à gauche, à droite, à gauche. Les buffs visibles restent compacts ; sur une barre mixte horizontale, les buffs du joueur et de la cible s'étendent depuis le centre sur une seule rangée.")
T("The socket window is available only in Retail", "La fenêtre de sertissage n'est disponible que sur Retail")
T("The stack condition uses Glow at stacks and Stack comparison. Buff absence cannot drive a combat glow through the native aura-slot API.", "La condition utilise le seuil de lueur et la comparaison des cumuls. L'absence d'une amélioration ne peut pas déclencher une lueur en combat via l'API native des emplacements d'aura.")
T("Theme", "Thème")
T("Theme-colored icon outline", "Contour d'icône aux couleurs du thème")
T("These apply to every bar. The standalone assisted icon follows Blizzard's assisted combat highlight; enable that highlight in the game's Combat options. Its position is available in MSUF Edit Mode. Action bar presses show on cooldown icons only with the MSUF Suite action bars.", "Ces réglages s'appliquent à toutes les barres. L'icône autonome suit la surbrillance d'assistance au combat de Blizzard ; activez-la dans les options de combat du jeu. Sa position se règle dans le mode Édition de MSUF. Les pressions de la barre d'actions ne s'affichent sur les icônes de recharge qu'avec les barres d'actions de MSUF Suite.")
