T("These choices apply to this spell on every bar and specialization.", "Ces choix s'appliquent à ce sort sur chaque barre et chaque spécialisation.")
T("These settings apply to all bars until a bar uses its own style.", "Ces réglages s'appliquent à toutes les barres tant qu'une barre n'utilise pas son propre style.")
