T("Uses Blizzard's Sell All Junk action when a merchant opens, including its per-bag exclusions. Hold Shift while opening the merchant to skip selling. The optional chat line confirms the request, not completed sales.", "Utilise l'action Vendre toute la camelote de Blizzard à l'ouverture d'un marchand, y compris ses exclusions par sac. Maintenez Maj en ouvrant le marchand pour ne pas vendre. La ligne de discussion facultative confirme la demande, pas les ventes effectuées.")
