T("Warn when your pet is missing or dead. By default, the missing warning applies to Hunters and Warlocks; the dead warning applies to any class with a pet. MSUF Edit Mode moves the alert.", "Avertit si votre mascotte est absente ou morte. Par défaut, l'avertissement d'absence concerne les chasseurs et les démonistes ; celui de mort concerne toutes les classes avec mascotte. Le mode Édition MSUF permet de déplacer l'alerte.")
