T("• No idle OnUpdate; a window corner drag runs one only while the mouse button is held\n• No repeating tickers; short one-shot timers only batch layout and hover updates\n• One frame walk per session, when the window skin is first enabled, adopts existing panel buttons\n• No aura or nameplate listeners; unit events only for the Micro Bar portrait and open character panels\n• Combat-state events only pause and resume deferred work and close open option popups\n• One shared ADDON_LOADED dispatcher only while catalog targets are pending\n• External weak-key runtime state", "• Pas d'OnUpdate au repos ; le glissement d'un coin de fenêtre n'en lance un que tant que le bouton de la souris est enfoncé\n• Pas de tickers répétitifs ; de courts minuteurs ponctuels ne font que regrouper les mises à jour de disposition et de survol\n• Un seul parcours des cadres par session, lors de la première activation de l'habillage des fenêtres, adopte les boutons de panneau existants\n• Aucun écouteur d'auras ni de barres d'info ; des événements d'unité seulement pour le portrait de la micro-barre et les panneaux de personnage ouverts\n• Les événements d'état de combat ne font que suspendre et reprendre le travail différé et fermer les fenêtres d'options ouvertes\n• Un seul répartiteur ADDON_LOADED partagé, uniquement tant que des cibles du catalogue sont en attente\n• État d'exécution externe à clés faibles")
